#!/bin/sh
# INOEX_SETUP_V1
# INOex 웹하드 로그 자동 수집 — 작업 스케줄러(사용자: root, 매일 03:00) '사용자 정의 스크립트' 칸에 이 내용 전체를 붙여넣습니다.
# 하는 일: (코드 버전이 바뀐 때만) 내장된 코드를 풀어 설치 → 로그센터 전송 로그를 읽어 누적 → 집계 보고를 출력(결과 메일 본문).
# 지키는 것: logs.env, config/webhard.yaml, data 는 덮어쓰지 않습니다. 계정 이름·IP 는 출력하지 않습니다.
BASE="${BASE:-/volume1/docker/inoex-webhard}"
KIT_VERSION="abfa0306de20"
mkdir -p "$BASE" || { echo "폴더를 만들 수 없습니다: $BASE"; echo "RESULT: FAIL"; exit 1; }
if [ "$(cat "$BASE/.installed_version" 2>/dev/null)" != "$KIT_VERSION" ]; then
  echo "== 코드 설치 ($KIT_VERSION)"
  TMP="$(mktemp -d)" || { echo "임시 폴더를 만들 수 없습니다"; echo "RESULT: FAIL"; exit 1; }
  # 내장 코드는 이 스크립트 맨 아래의 heredoc(자기 자신을 다시 읽지 않으므로 DSM 이 스크립트를 어떻게 실행하든 동작한다)
  base64 -d <<'__INOEX_PAYLOAD__' | tar xzf - -C "$TMP" || { echo "내장 코드를 풀지 못했습니다(붙여넣기가 중간에 잘렸을 수 있습니다)"; rm -rf "$TMP"; echo "RESULT: FAIL"; exit 1; }
